static void devnet_inactive_callback ( struct vnode * dvp ) { struct sdev_node * sdvp = VTOSDEV ( dvp ) ; dls_dl_handle_t ddh ; ASSERT ( dvp -> v_type == VCHR ) ; rw_enter ( & sdvp -> sdev_contents , RW_WRITER ) ; ddh = sdvp -> sdev_private ; sdvp -> sdev_private = NULL ; sdvp -> sdev_flags |= SDEV_ATTR_INVALID ; rw_exit ( & sdvp -> sdev_contents ) ; if ( ddh != NULL ) { dls_devnet_close ( ddh ) ; } } 